B.aNw=new A.an("sfx_t14_lamp_flicker",0.001,1,null,1)
B.a41=s([B.aNw],t.e)
B.aYd=new A.ih("N\u011bkdy se mus\xed\u0161 o kousek vr\xe1tit, a\u0165 se dostane\u0161 d\xe1l.","P\u0159elij ze zvednut\xe9 n\xe1doby do t\xe9, kter\xe1 sv\xedt\xed. Cesta dop\u0159edu n\u011bkdy vede kousek zp\xe1tky.")
B.a42=s([B.aYd],t.AE)
B.VJ=new A.k(0.7019607843137254,1,0.8784313725490196,0.5490196078431373,B.d)
B.VF=new A.k(0.25098039215686274,1,0.8784313725490196,0.5490196078431373,B.d)
B.T1=new A.k(0,1,0.8784313725490196,0.5490196078431373,B.d)
B.a43=s([B.VJ,B.VF,B.T1],t.W)
B.ah9=new A.b1("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.ba_=new A.A(56,56)
B.aw=new A.lS("ema","assets/images/stories/museum/story/portrait_ema.webp")
B.a5n=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.aUf=new A.a8(B.aw,B.a5n,!1)
B.aF=new A.lS("jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.a4M=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.aUy=new A.a8(B.aF,B.a4M,!1)
B.aI=new A.lS("nela","assets/images/stories/museum/story/portrait_nela.webp")
B.a9Y=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.aV0=new A.a8(B.aI,B.a9Y,!1)
B.ahr=new A.b1("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.a2U=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.aW4=new A.a8(B.aw,B.a2U,!1)
B.ahs=new A.b1("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.aat=s([B.ah9,B.aUf,B.aUy,B.aV0,B.ahr,B.aW4,B.ahs],t.a)
B.aX8=new A.cy("story_01",B.aat)
B.agO=new A.b1("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.a5K=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.aU0=new A.a8(B.aw,B.a5K,!1)
B.a4s=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.aU_=new A.a8(B.aF,B.a4s,!1)
B.agF=new A.b1("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.aa3=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.aVg=new A.a8(B.aI,B.aa3,!1)
B.a4I=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.aTW=new A.a8(B.aF,B.a4I,!1)
B.agJ=new A.b1("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.a0V=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.aWm=new A.a8(B.aw,B.a0V,!1)
B.agN=new A.b1("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.a4f=s([B.agO,B.aU0,B.aU_,B.agF,B.aVg,B.aTW,B.agJ,B.aWm,B.agN],t.a)
B.aX3=new A.cy("story_02",B.a4f)
B.ahb=new A.b1("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.a3N=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.aW2=new A.a8(B.aF,B.a3N,!1)
B.a83=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.aUB=new A.a8(B.aw,B.a83,!1)
B.a9w=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.aVY=new A.a8(B.aI,B.a9w,!1)
B.agH=new A.b1("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.tx=new A.lS("baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.aaY=s(["\u201eRuhe\u2026\u201c"],t.s)
B.aUp=new A.a8(B.tx,B.aaY,!0)
B.a4H=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.aWz=new A.a8(B.aF,B.a4H,!1)
B.ahk=new A.b1("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.ahl=new A.b1("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.abK=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.aVR=new A.a8(B.aI,B.abK,!1)
B.a7q=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.aUL=new A.a8(B.aw,B.a7q,!1)
B.a8d=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.aVj=new A.a8(B.aF,B.a8d,!1)
B.aaU=s([B.ahb,B.aW2,B.aUB,B.aVY,B.agH,B.aUp,B.aWz,B.ahk,B.ahl,B.aVR,B.aUL,B.aVj],t.a)
B.aXc=new A.cy("story_03",B.aaU)
B.ahL=new A.b1("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.abP=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.aVV=new A.a8(B.aF,B.abP,!1)
B.ahB=new A.b1("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.a31=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.aU1=new A.a8(B.aI,B.a31,!1)
B.a4w=s([B.ahL,B.aVV,B.ahB,B.aU1],t.a)
B.aXd=new A.cy("story_04",B.a4w)
B.agM=new A.b1("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.a7y=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.aWx=new A.a8(B.aw,B.a7y,!1)
B.a1U=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.aUk=new A.a8(B.aI,B.a1U,!1)
B.ahp=new A.b1("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.abX=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.aUN=new A.a8(B.aI,B.abX,!1)
B.a4O=s([B.agM,B.aWx,B.aUk,B.ahp,B.aUN],t.a)
B.aXr=new A.cy("story_05",B.a4O)
B.agx=new A.b1("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.abs=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.aVJ=new A.a8(B.aF,B.abs,!1)
B.a56=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.aTX=new A.a8(B.aI,B.a56,!1)
B.agr=new A.b1("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.a8P=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.aTT=new A.a8(B.aw,B.a8P,!1)
B.aaJ=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.aV9=new A.a8(B.aF,B.aaJ,!1)
B.a9v=s([B.agx,B.aVJ,B.aTX,B.agr,B.aTT,B.aV9],t.a)
B.aXm=new A.cy("story_06",B.a9v)
B.ahf=new A.b1("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.a6n=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.aU4=new A.a8(B.aF,B.a6n,!1)
B.aht=new A.b1("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.a87=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.aUU=new A.a8(B.aw,B.a87,!1)
B.acy=s([B.ahf,B.aU4,B.aht,B.aUU],t.a)
B.aX9=new A.cy("story_07",B.acy)
B.ahq=new A.b1("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.a2i=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.aVP=new A.a8(B.aI,B.a2i,!1)
B.ah6=new A.b1("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.a3u=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.aW_=new A.a8(B.aI,B.a3u,!1)
B.ahm=new A.b1("Jon\xe1\u0161 se zhluboka nadechne.")
B.a2t=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.aVx=new A.a8(B.aF,B.a2t,!1)
B.a15=s([B.ahq,B.aVP,B.ah6,B.aW_,B.ahm,B.aVx],t.a)
B.aXa=new A.cy("story_08",B.a15)
B.ah1=new A.b1("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.a9r=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.aVr=new A.a8(B.aF,B.a9r,!1)
B.a2N=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.aWg=new A.a8(B.aw,B.a2N,!1)
B.a3k=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.aVq=new A.a8(B.aF,B.a3k,!1)
B.a9z=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.aWu=new A.a8(B.aI,B.a9z,!1)
B.a4T=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.aVH=new A.a8(B.aF,B.a4T,!1)
B.a37=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.aUx=new A.a8(B.aI,B.a37,!1)
B.a6p=s([B.ah1,B.aVr,B.aWg,B.aVq,B.aWu,B.aVH,B.aUx],t.a)
B.aX2=new A.cy("story_09",B.a6p)
B.agu=new A.b1("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.a3P=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.aVb=new A.a8(B.aI,B.a3P,!1)
B.ahE=new A.b1("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.a5q=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.aVu=new A.a8(B.aF,B.a5q,!1)
B.abH=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.aVy=new A.a8(B.aw,B.abH,!1)
B.a5Y=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.aUm=new A.a8(B.aI,B.a5Y,!1)
B.a0G=s([B.agu,B.aVb,B.ahE,B.aVu,B.aVy,B.aUm],t.a)
B.aXl=new A.cy("story_10",B.a0G)
B.ahn=new A.b1("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.acf=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.aVa=new A.a8(B.aF,B.acf,!1)
B.a3r=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.aUs=new A.a8(B.aw,B.a3r,!1)
B.agv=new A.b1("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.am=new A.lS("clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.a2l=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.aWt=new A.a8(B.am,B.a2l,!0)
B.ahC=new A.b1("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.a8M=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.aWa=new A.a8(B.am,B.a8M,!0)
B.aaL=s(["\u201eKdo jste?\u201c"],t.s)
B.aVU=new A.a8(B.aw,B.aaL,!1)
B.a2C=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.aWv=new A.a8(B.am,B.a2C,!0)
B.ahj=new A.b1("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.abi=s([B.ahn,B.aVa,B.aUs,B.agv,B.aWt,B.ahC,B.aWa,B.aVU,B.aWv,B.ahj],t.a)
B.aX_=new A.cy("story_11",B.abi)
B.ahi=new A.b1("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.a4S=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.aUh=new A.a8(B.am,B.a4S,!1)
B.ah7=new A.b1("Nela se pod\xedv\xe1 na mobil.")
B.a8Y=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.aVD=new A.a8(B.aI,B.a8Y,!1)
B.abY=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.aVZ=new A.a8(B.am,B.abY,!1)
B.ah0=new A.b1("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.a6G=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.aUE=new A.a8(B.aF,B.a6G,!1)
B.a9g=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.aU3=new A.a8(B.am,B.a9g,!1)
B.a99=s([B.ahi,B.aUh,B.ah7,B.aVD,B.aVZ,B.ah0,B.aUE,B.aU3],t.a)
B.aXk=new A.cy("story_12",B.a99)
B.ac9=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.aUo=new A.a8(B.aw,B.ac9,!1)
B.agK=new A.b1("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.abE=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.aVC=new A.a8(B.am,B.abE,!1)
B.a2F=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.aVO=new A.a8(B.aw,B.a2F,!1)
B.ab1=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.aUu=new A.a8(B.am,B.ab1,!1)
B.agB=new A.b1("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.a5O=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.aW9=new A.a8(B.am,B.a5O,!1)
B.agX=new A.b1("Nela zaklepe na brn\u011bn\xed.")
B.a2V=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.aUg=new A.a8(B.aI,B.a2V,!1)
B.agD=new A.b1("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.a7b=s([B.aUo,B.agK,B.aVC,B.aVO,B.aUu,B.agB,B.aW9,B.agX,B.aUg,B.agD],t.a)
B.aX6=new A.cy("story_13",B.a7b)
B.ahc=new A.b1("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.a6z=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.aUP=new A.a8(B.aw,B.a6z,!1)
B.aco=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.aUe=new A.a8(B.am,B.aco,!1)
B.a34=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.aWy=new A.a8(B.aI,B.a34,!1)
B.acu=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.aVn=new A.a8(B.aF,B.acu,!1)
B.ags=new A.b1("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.a63=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.aVv=new A.a8(B.am,B.a63,!1)
B.a3E=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.aTZ=new A.a8(B.aI,B.a3E,!1)
B.a4x=s([B.ahc,B.aUP,B.aUe,B.aWy,B.aVn,B.ags,B.aVv,B.aTZ],t.a)
B.aXg=new A.cy("story_14",B.a4x)
B.agI=new A.b1("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.a5h=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.aWB=new A.a8(B.am,B.a5h,!1)
B.ahx=new A.b1("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.a25=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.aUI=new A.a8(B.am,B.a25,!1)
B.aaR=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.aUJ=new A.a8(B.aF,B.aaR,!1)
B.abq=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.aUi=new A.a8(B.aI,B.abq,!1)
B.ahu=new A.b1("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.a6g=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.aW0=new A.a8(B.am,B.a6g,!1)
B.a0q=s([B.agI,B.aWB,B.ahx,B.aUI,B.aUJ,B.aUi,B.ahu,B.aW0],t.a)
B.aX5=new A.cy("story_15",B.a0q)
B.ahK=new A.b1("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.ab8=s(["\u201eKde je?\u201c"],t.s)
B.aWp=new A.a8(B.aF,B.ab8,!1)
B.ahv=new A.b1("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.a7a=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.aVf=new A.a8(B.am,B.a7a,!1)
B.aaQ=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.aUH=new A.a8(B.aw,B.aaQ,!1)
B.a3S=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.aWo=new A.a8(B.am,B.a3S,!1)
B.a3M=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.aUj=new A.a8(B.aw,B.a3M,!1)
B.aax=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.aUG=new A.a8(B.am,B.aax,!1)
B.a6V=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.aV7=new A.a8(B.aw,B.a6V,!1)
B.ahd=new A.b1("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.a1D=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.aUK=new A.a8(B.aw,B.a1D,!1)
B.a2A=s([B.ahK,B.aWp,B.ahv,B.aVf,B.aUH,B.aWo,B.aUj,B.aUG,B.aV7,B.ahd,B.aUK],t.a)
B.aXn=new A.cy("story_16",B.a2A)
B.agT=new A.b1("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.a5y=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.aW1=new A.a8(B.aF,B.a5y,!1)
B.agz=new A.b1("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.abU=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.aVe=new A.a8(B.aw,B.abU,!1)
B.aar=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.aUO=new A.a8(B.aI,B.aar,!1)
B.a5k=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.aWk=new A.a8(B.aw,B.a5k,!1)
B.a9I=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.aW3=new A.a8(B.aF,B.a9I,!1)
B.agQ=new A.b1("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.a7I=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.aVp=new A.a8(B.aI,B.a7I,!1)
B.agy=new A.b1("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.a2d=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.aUz=new A.a8(B.aF,B.a2d,!1)
B.a9K=s([B.agT,B.aW1,B.agz,B.aVe,B.aUO,B.aWk,B.aW3,B.agQ,B.aVp,B.agy,B.aUz],t.a)
B.aXh=new A.cy("story_17",B.a9K)
B.ahA=new A.b1("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.a0U=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.aW7=new A.a8(B.aI,B.a0U,!1)
B.agC=new A.b1("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.a6F=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.aVk=new A.a8(B.aF,B.a6F,!1)
B.a3B=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.aVl=new A.a8(B.am,B.a3B,!1)
B.a9_=s([B.ahA,B.aW7,B.agC,B.aVk,B.aVl],t.a)
B.aXq=new A.cy("story_18",B.a9_)
B.ah_=new A.b1("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.a93=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.aVo=new A.a8(B.am,B.a93,!1)
B.a73=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.aVd=new A.a8(B.aF,B.a73,!1)
B.a4z=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.aUc=new A.a8(B.am,B.a4z,!1)
B.ahF=new A.b1("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.a66=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.aU7=new A.a8(B.am,B.a66,!1)
B.ahG=new A.b1("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.a9m=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.aVL=new A.a8(B.tx,B.a9m,!0)
B.a3q=s([B.ah_,B.aVo,B.aVd,B.aUc,B.ahF,B.aU7,B.ahG,B.aVL],t.a)
B.aXi=new A.cy("story_19",B.a3q)
B.ahD=new A.b1("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.a98=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.aUd=new A.a8(B.aF,B.a98,!1)
B.a5C=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.aVG=new A.a8(B.aw,B.a5C,!1)
B.ah8=new A.b1("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.a3X=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.aUl=new A.a8(B.am,B.a3X,!1)
B.aan=s([B.ahD,B.aUd,B.aVG,B.ah8,B.aUl],t.a)
B.aXb=new A.cy("story_20",B.aan)
B.agt=new A.b1("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.ace=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.aUw=new A.a8(B.am,B.ace,!1)
B.ahe=new A.b1("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.a4o=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.aUM=new A.a8(B.am,B.a4o,!1)
B.a7J=s([B.agt,B.aUw,B.ahe,B.aUM],t.a)
B.aXs=new A.cy("story_21",B.a7J)
B.ah3=new A.b1("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.a3m=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.aW5=new A.a8(B.am,B.a3m,!1)
B.acz=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.aTU=new A.a8(B.am,B.acz,!1)
B.aaM=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.aU6=new A.a8(B.aF,B.aaM,!1)
B.a59=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.aUZ=new A.a8(B.am,B.a59,!1)
B.a0u=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.aUS=new A.a8(B.am,B.a0u,!1)
B.acj=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.aV8=new A.a8(B.aw,B.acj,!1)
B.a4y=s([B.ah3,B.aW5,B.aTU,B.aU6,B.aUZ,B.aUS,B.aV8],t.a)
B.aXp=new A.cy("story_22",B.a4y)
B.aaS=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.aV1=new A.a8(B.am,B.aaS,!1)
B.a62=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.aUb=new A.a8(B.aw,B.a62,!1)
B.aaD=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.aVQ=new A.a8(B.aI,B.aaD,!1)
B.agV=new A.b1("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.a5H=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.aU9=new A.a8(B.am,B.a5H,!1)
B.a8R=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.aVM=new A.a8(B.aw,B.a8R,!1)
B.a3Q=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.aWq=new A.a8(B.aI,B.a3Q,!1)
B.a75=s([B.aV1,B.aUb,B.aVQ,B.agV,B.aU9,B.aVM,B.aWq],t.a)
B.aXf=new A.cy("story_23",B.a75)
B.agS=new A.b1("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.abG=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.aVs=new A.a8(B.aw,B.abG,!1)
B.ahw=new A.b1("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.aaf=s(["\u201eSrdce muzea.\u201c"],t.s)
B.aVK=new A.a8(B.am,B.aaf,!1)
B.agW=new A.b1("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.ahH=new A.b1("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.a94=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.aUQ=new A.a8(B.tx,B.a94,!1)
B.ahy=new A.b1("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.a5X=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.aVi=new A.a8(B.aI,B.a5X,!1)
B.a3I=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.aUR=new A.a8(B.aF,B.a3I,!1)
B.a4r=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.aV4=new A.a8(B.am,B.a4r,!1)
B.acv=s([B.agS,B.aVs,B.ahw,B.aVK,B.agW,B.ahH,B.aUQ,B.ahy,B.aVi,B.aUR,B.aV4],t.a)
B.aX0=new A.cy("story_24",B.acv)
B.agU=new A.b1("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.aaq=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.aVt=new A.a8(B.am,B.aaq,!1)
B.a9x=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.aV3=new A.a8(B.am,B.a9x,!1)
B.a6i=s([B.agU,B.aVt,B.aV3],t.a)
B.aWV=new A.cy("story_25",B.a6i)
B.aho=new A.b1("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.a4u=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.aW6=new A.a8(B.aI,B.a4u,!1)
B.aaX=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.aV2=new A.a8(B.aw,B.aaX,!1)
B.ah4=new A.b1("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.a4d=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.aWl=new A.a8(B.aw,B.a4d,!1)
B.a69=s([B.aho,B.aW6,B.aV2,B.ah4,B.aWl],t.a)
B.aXo=new A.cy("story_26",B.a69)
B.ahJ=new A.b1("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.a7m=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.aWc=new A.a8(B.aw,B.a7m,!1)
B.a6a=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.aVB=new A.a8(B.aI,B.a6a,!1)
B.agA=new A.b1("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.a5g=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.aUA=new A.a8(B.aF,B.a5g,!1)
B.ah5=new A.b1("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.abt=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.aVh=new A.a8(B.aw,B.abt,!1)
B.agR=new A.b1("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.agP=new A.b1("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.abA=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.aWb=new A.a8(B.aI,B.abA,!1)
B.a7D=s([B.ahJ,B.aWc,B.aVB,B.agA,B.aUA,B.ah5,B.aVh,B.agR,B.agP,B.aWb],t.a)
B.aX7=new A.cy("story_27",B.a7D)
